trait EvictionPolicy<K> { fn pick(&self, keys: &[K]) -> K; }
struct Lru;
impl<K: Copy> EvictionPolicy<K> for Lru { fn pick(&self, keys: &[K]) -> K { keys[0] } }

struct Cache<K, V, P: EvictionPolicy<K>> { policy: P, items: Vec<(K, V)> }

impl<K, V, P: EvictionPolicy<K>> Cache<K, V, P> {
    fn victim(&self, keys: &[K]) -> K { self.policy.pick(keys) }
}
